#ifndef UI_STATE_MACHINE_H
#define UI_STATE_MACHINE_H

#include "ui_types.h"

/* -----------------------------------------------------------------------
 * ui_state_machine.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: Tony; Brendon (integrator) added the fault and debug screen API (28 Oct 2026) and the two rules for following Jack (29-30 Oct 2026, with an AI coding assistant).
 * BJT2 Sound Modulating Toy — UI State Machine Public API
 * Author: Tony (Display/UI subsystem)
 *
 * Five public functions form the complete interface, plus two rules the
 * firmware uses to follow Jack's status (ui_follow_jack_idle, the REC
 * clock). All logic is hardware-independent. No HAL calls anywhere in
 * this module.
 * ----------------------------------------------------------------------- */

/* Trust Jack's "idle" this long after Tony's last command even when his
 * status does not carry that command's seq (it was lost to a full queue). */
#define UI_CMD_RECONCILE_MS 1000U

/**
 * ui_init
 * Initialises a ui_state_t struct to safe known defaults.
 * Must be called once before any ui_process_event calls.
 *
 * @param s  Pointer to the ui_state_t to initialise. NULL is ignored.
 */
void ui_init(ui_state_t *s);

/**
 * ui_process_event
 * Core dispatcher. Routes one input event to the handler for the
 * currently active screen. Events irrelevant to the current screen
 * are silently ignored — no cross-screen state corruption is possible.
 *
 * EVENT_GO_HOME (BACK, or the HOME button) is handled globally and
 * always navigates to home regardless of current screen. If a file is
 * PAUSED it also stops it (playback -> IDLE), which frees the SD card; a
 * PLAYING file keeps looping and a recording carries on. The encoder
 * push (EVENT_MUTE_TOGGLE) is also global: it selects on the Home,
 * Effects and File screens and toggles mute on every other screen.
 *
 * On UI_SCREEN_FAULT every event (except EVENT_NONE) only dismisses the
 * fault screen and returns to fault_return_screen; nothing else changes.
 *
 * On UI_SCREEN_DEBUG only three events change state (see ui_enter_debug);
 * the global events do not apply there.
 *
 * @param s      Pointer to current UI state. NULL is ignored.
 * @param event  The input event to process.
 */
void ui_process_event(ui_state_t *s, ui_event_t event);

/**
 * ui_enter_debug
 * Opens the hidden debug screen (UI_SCREEN_DEBUG) on its first page with
 * the cursor on item 0. Only from the Home screen: on any other screen
 * (the fault overlay and the debug screen itself included) nothing
 * changes. The firmware calls it once BACK has been held for 2 s on Home
 * (debug_hold_update() in debug_menu.h); nothing on Home advertises it.
 *
 * While the debug screen shows, ui_process_event() does:
 *   EVENT_GO_HOME (short BACK)         -> back to Home
 *   EVENT_VOLUME_UP (encoder CW)       -> debug_cursor_next()
 *   EVENT_VOLUME_DOWN (encoder CCW)    -> debug_cursor_prev()
 *   any other event                    -> no state change at all.
 * Encoder push, PLAY and REC are the page's own actions (play a test
 * pattern, inject a fault ...), which the firmware glue performs, so
 * here they must not toggle mute, start playback or recording, or
 * navigate. A fault overlay over the debug screen returns to it.
 *
 * @param s  Pointer to current UI state. NULL is ignored.
 */
void ui_enter_debug(ui_state_t *s);

/**
 * ui_show_fault
 * Opens the modal fault screen (UI_SCREEN_FAULT) with the given text.
 *   - Not on the fault screen: remembers the current screen as
 *     fault_return_screen and switches to UI_SCREEN_FAULT.
 *   - Already showing the SAME source + code: no change (a fault that is
 *     still present does not "re-open" anything).
 *   - Showing a different fault: replaces the text, keeps the original
 *     return screen.
 * line2/line3 are cut to 20 characters (one size-2 line); NULL = empty.
 * While the fault screen is up, ui_process_event() dismisses it on any
 * event (back to fault_return_screen) and consumes that event.
 *
 * @param s       Pointer to current UI state. NULL is ignored.
 * @param source  ui_fault_source_t (mirrors FaultSource_t).
 * @param code    Producer's fault code; UI_FAULT_CODE_SIMULATED marks an
 *                injected one.
 * @return        true if the screen opened or its content changed (the
 *                firmware then redraws it), false otherwise.
 */
bool ui_show_fault(ui_state_t *s, uint8_t source, uint8_t code,
                   const char *line2, const char *line3);

/**
 * ui_get_effective_volume
 * Returns the volume level to send to the DAC. When muted this
 * returns 0 while preserving s->volume, so unmuting restores
 * the original level without any extra state.
 *
 * @param s  Pointer to current UI state.
 * @return   Effective volume 0-100, or 0 if s is NULL.
 */
uint8_t ui_get_effective_volume(const ui_state_t *s);

/**
 * ui_follow_jack_idle
 * Should the UI follow Jack to IDLE (his playback ended, he refused a
 * RESUME, a delete stopped it, the card was pulled)? Jack is the
 * authority on the transport, but a status he published BEFORE taking
 * Tony's newest command (an "idle" from just before a PLAY_START) must
 * not undo that press. Every command Tony sends carries a number (seq),
 * and Jack's status says which one he has handled last, so:
 *   follow when Jack is idle (not recording, jack_playing 0: 3 is
 *   "preparing", never idle) and the UI is not, and
 *     - the status carries Tony's newest seq (at once), or
 *     - more than UI_CMD_RECONCILE_MS have passed since the last command
 *       (the old rule, for a command lost to a full queue).
 *
 * @param ui_playback     The UI's transport.
 * @param jack_recording  Jack's status: recording.
 * @param jack_playing    Jack's status: 0 idle, 1 playing, 2 paused, 3 preparing.
 * @param seq_matches     His cmd_seq is Tony's newest command seq.
 * @param ms_since_cmd    Milliseconds since Tony's last command.
 * @return                true: set the UI's transport to IDLE (no command).
 */
bool ui_follow_jack_idle(playback_state_t ui_playback, bool jack_recording, uint8_t jack_playing,
                         bool seq_matches, uint32_t ms_since_cmd);

/**
 * ui_rec_clock_start
 * The Record screen's clock starts when Jack first says he records, in his
 * status or in his RECORD_START ack, whichever Tony reads first (usually
 * the status: he publishes it just before the ack), while the UI is
 * recording and the clock is not running yet, so the timer never stays at
 * 0:00.
 *
 * @return  true: start the clock now.
 */
bool ui_rec_clock_start(playback_state_t ui_playback, bool jack_recording, bool clock_running);

#endif /* UI_STATE_MACHINE_H */
